-- Tend · .tend/tend.db · schema v1
-- Nothing has shipped yet, so this file is edited in place; migrations start with the first
-- release. Scope: notes, tasks, people, timers, labels, the Library. Calendar, events and reminders
-- come later (docs/later/).
--
-- Conventions
--   * every table has `id TEXT PRIMARY KEY`: a ULID generated by the app, never replaced, and
--     never reused (a deleted id stays deleted). A few rows that exist on every device and are
--     never deleted use a fixed id: settings = their key, default enum rows = '<KIND>:<VALUE>',
--     root folders = 'root'. Link rows get a fresh ULID each time they are added; their UNIQUE
--     key stops duplicates, and sync merges two devices' rows for the same key.
--   * enum kinds, enum values and link types are SCREAMING_SNAKE_CASE; the app holds them as
--     constants (src-tauri/src/enums, src/lib/enums), and checks them, not this file
--   * synced tables have `updated_at` (ms since the Unix epoch, UTC), set by the app on every
--     insert and update (sync keeps the newest; see docs/v1-sync-spec.md)
--   * other moments are INTEGER milliseconds since the Unix epoch, UTC (*_at columns)
--   * local calendar values stay TEXT: dates 'YYYY-MM-DD', times 'HH:MM' (24h)
--   * booleans are INTEGER 0/1; colors are '#rrggbb'
--   * every table is STRICT (SQLite >= 3.37); the app opens with foreign_keys = ON and WAL
--   * this file is migration 1 (rusqlite_migration); the schema version is PRAGMA user_version
--   * the vault folder is the notes root; Tend's own files live in .tend/. Paths are relative to
--     the vault: note bodies 'work/q4_plan.md', attached files '.tend/attachments/<id>.pdf';
--     folder paths '' (root), 'work', 'work/infra'. Folder and note file names follow the name
--     rule ^[a-z0-9]+(_[a-z0-9]+)*$


-------------------------------------------------------------------------------
-- 0. App identity (the "incompatible db" check reads app_id; the version is PRAGMA user_version). Local.
-------------------------------------------------------------------------------
CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
) STRICT;
INSERT INTO meta (key, value) VALUES
  ('app_id', 'tend'),
  ('created_at', CAST(unixepoch('subsec') * 1000 AS INTEGER));

-- Key/value settings (value is JSON). id = key. Which keys sync is decided by the app.
CREATE TABLE settings (
  id         TEXT PRIMARY KEY,
  key        TEXT NOT NULL UNIQUE,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 1. Enums and links (docs/decisions.md §16)
-------------------------------------------------------------------------------
-- Every list the user can change: task statuses, task labels, word kinds, tags. `value` never
-- changes; `label` is what the user sees. `meta` holds the rest (color, position, lookup) as JSON,
-- checked by the app. Default rows can't be deleted. A BLOCKED row stays in its list but can't be
-- put on anything new; the app removes its links (tend_links) when it blocks it, and unblocking
-- brings none of them back.
CREATE TABLE tend_enums (
  id         TEXT PRIMARY KEY,
  kind       TEXT NOT NULL,              -- TASK_STATUS, TASK_LABEL, WORD_KIND, TAG
  value      TEXT NOT NULL,              -- SCREAMING_SNAKE_CASE
  label      TEXT NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
  status     TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'BLOCKED')),
  meta       TEXT NOT NULL DEFAULT '{}',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (kind, value)
) STRICT;
INSERT INTO tend_enums (id, kind, value, label, is_default, meta, created_at, updated_at) VALUES
  ('TASK_STATUS:NOT_STARTED', 'TASK_STATUS', 'NOT_STARTED', 'Not started', 1, '{"color":"#7d8995","position":0}',    0, 0),
  ('TASK_STATUS:IN_PROGRESS', 'TASK_STATUS', 'IN_PROGRESS', 'In progress', 1, '{"color":"#1259d3","position":1}',    0, 0),
  ('TASK_STATUS:DONE',        'TASK_STATUS', 'DONE',        'Done',        1, '{"color":"#1e7a55","position":1000}', 0, 0);

CREATE TRIGGER tend_enums_keep_defaults BEFORE DELETE ON tend_enums
WHEN OLD.is_default = 1
BEGIN SELECT RAISE(ABORT, 'default enum row cannot be deleted'); END;

-- A record carrying an enum (a tag, a label) or an attachment. For an attachment, target_kind is
-- '' (not NULL, so the unique key holds) and target_value is the attachment id. Rows are removed by
-- the triggers below when their source, attachment or enum row is deleted.
CREATE TABLE tend_links (
  id           TEXT PRIMARY KEY,
  source_type  TEXT NOT NULL,            -- TASK, NOTE, COMMENT, PERSON, WORD, SNAP, REF
  source_id    TEXT NOT NULL,
  target_type  TEXT NOT NULL,            -- ENUM, ATTACHMENT
  target_kind  TEXT NOT NULL DEFAULT '',
  target_value TEXT NOT NULL,
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  UNIQUE (source_type, source_id, target_type, target_kind, target_value)
) STRICT;
CREATE INDEX tend_links_target ON tend_links (target_type, target_kind, target_value);

CREATE TRIGGER tend_enums_drop_links AFTER DELETE ON tend_enums
BEGIN
  DELETE FROM tend_links
  WHERE target_type = 'ENUM' AND target_kind = OLD.kind AND target_value = OLD.value;
END;

-------------------------------------------------------------------------------
-- 2. Attachments: every file Tend knows, at its place in the vault.
-------------------------------------------------------------------------------
-- A note's body is an attachment (its file in the vault); an attached file lives in
-- .tend/attachments/<id>.<ext>.
-- `mtime` and `missing_at` describe this device's copy of the file and are not synced.
CREATE TABLE attachments (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL UNIQUE,       -- 'work/q4_plan.md', '.tend/attachments/<id>.pdf'
  name       TEXT NOT NULL,              -- display / download name: 'invoice march.pdf', 'plan.md'
  mime_type  TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256     TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  mtime      INTEGER NOT NULL DEFAULT 0, -- local: file mtime when last read
  missing_at INTEGER                     -- local: file gone from disk; purged after a grace period
) STRICT;

-- Where an attachment is used: tend_links rows with target_type 'ATTACHMENT'. Linking a note
-- means linking its attachment.
CREATE TRIGGER attachments_drop_links AFTER DELETE ON attachments
BEGIN
  DELETE FROM tend_links
  WHERE target_type = 'ATTACHMENT' AND target_kind = '' AND target_value = OLD.id;
END;

-------------------------------------------------------------------------------
-- 3. Notes. The body is a markdown file (an attachment in the vault); the note is the record.
-------------------------------------------------------------------------------
-- A note's title is part of its file (the first `# heading`); the database keeps no copy. The file
-- name follows the name rule: a new note's title gives it its slug. Renaming or moving a note
-- changes only attachments.path, and the note's id stays, so tags and links follow it. On vault
-- open and on outside changes the app scans the vault and matches files to attachments by path.
CREATE TABLE note_folders (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL UNIQUE,       -- '' (the vault root), 'work', 'work/infra'
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  missing_at INTEGER                     -- local: folder gone from disk
) STRICT;
INSERT INTO note_folders (id, path, created_at, updated_at) VALUES
  ('root', '', CAST(unixepoch('subsec') * 1000 AS INTEGER), CAST(unixepoch('subsec') * 1000 AS INTEGER));

CREATE TABLE notes (
  id            TEXT PRIMARY KEY,
  attachment_id TEXT NOT NULL UNIQUE REFERENCES attachments(id) ON DELETE CASCADE,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
) STRICT;

CREATE TRIGGER notes_drop_links AFTER DELETE ON notes
BEGIN DELETE FROM tend_links WHERE source_type = 'NOTE' AND source_id = OLD.id; END;

-------------------------------------------------------------------------------
-- 4. People (own section; birthdays shown in the list, task assignees)
-------------------------------------------------------------------------------
CREATE TABLE people (
  id                TEXT PRIMARY KEY,
  first_name        TEXT NOT NULL,
  last_name         TEXT NOT NULL DEFAULT '',
  nickname          TEXT,                  -- shown instead of first + last when set
  dob_year          INTEGER,               -- optional: birthday known, year unknown
  dob_month         INTEGER CHECK (dob_month BETWEEN 1 AND 12),
  dob_day           INTEGER CHECK (dob_day BETWEEN 1 AND 31),
  tob               TEXT CHECK (tob IS NULL OR tob GLOB '[0-2][0-9]:[0-5][0-9]'),
  notes             TEXT NOT NULL DEFAULT '',
  birthday_reminder INTEGER NOT NULL DEFAULT 1 CHECK (birthday_reminder IN (0, 1)),   -- stored now, hidden in v1 UI
  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL,
  CHECK ((dob_month IS NULL) = (dob_day IS NULL))
) STRICT;
CREATE INDEX people_name ON people(first_name COLLATE NOCASE, last_name COLLATE NOCASE);

-- Phones, emails, addresses: any number of each, value + label ('personal', 'work', …)
CREATE TABLE person_contacts (
  id         TEXT PRIMARY KEY,
  person_id  TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('phone', 'email', 'address')),
  value      TEXT NOT NULL,
  label      TEXT NOT NULL DEFAULT '',
  position   INTEGER NOT NULL,           -- order within (person, kind); first = primary
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX person_contacts_person ON person_contacts(person_id, kind, position);

CREATE TRIGGER people_drop_links AFTER DELETE ON people
BEGIN DELETE FROM tend_links WHERE source_type = 'PERSON' AND source_id = OLD.id; END;

-------------------------------------------------------------------------------
-- 5. Tasks
-------------------------------------------------------------------------------
-- Folders are identified by id; tasks point at their folder's path (renaming a folder rewrites
-- the paths below it, and tasks follow through ON UPDATE CASCADE). One root ('', id 'root'),
-- whose display name is settings tasks.root_name. Explorer sorts folders alphabetically.
-- Statuses (TASK_STATUS) and labels (TASK_LABEL) are rows in tend_enums; a task holds its status
-- value, and the app refuses to delete a status that is in use.
CREATE TABLE task_folders (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL UNIQUE,       -- '' (root), 'work', 'work/infra'
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
INSERT INTO task_folders (id, path, created_at, updated_at) VALUES
  ('root', '', CAST(unixepoch('subsec') * 1000 AS INTEGER), CAST(unixepoch('subsec') * 1000 AS INTEGER));

CREATE TABLE tasks (
  id           TEXT PRIMARY KEY,
  path         TEXT NOT NULL REFERENCES task_folders(path) ON UPDATE CASCADE ON DELETE RESTRICT,
  parent_id    TEXT REFERENCES tasks(id) ON DELETE CASCADE,       -- subtask of … (one level)
  title        TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'NOT_STARTED',                -- a TASK_STATUS value
  description  TEXT NOT NULL DEFAULT '',                          -- markdown
  due_date     TEXT CHECK (due_date IS NULL OR due_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  due_time     TEXT CHECK (due_time IS NULL OR due_time GLOB '[0-2][0-9]:[0-5][0-9]'),
  assignee_id  TEXT REFERENCES people(id) ON DELETE SET NULL,
  order_key    TEXT NOT NULL,            -- one global fractional index (list, board, My day)
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  completed_at INTEGER                   -- set when status becomes DONE
) STRICT;
CREATE INDEX tasks_path     ON tasks(path);
CREATE INDEX tasks_parent   ON tasks(parent_id);
CREATE INDEX tasks_status   ON tasks(status);
CREATE INDEX tasks_due      ON tasks(due_date, due_time) WHERE due_date IS NOT NULL;
CREATE INDEX tasks_assignee ON tasks(assignee_id) WHERE assignee_id IS NOT NULL;
CREATE INDEX tasks_order    ON tasks(order_key);

-- My day: tasks due today are in by default; rows are manual overrides for a given day.
CREATE TABLE my_day (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  day        TEXT NOT NULL,              -- 'YYYY-MM-DD'
  included   INTEGER NOT NULL CHECK (included IN (0, 1)),
  updated_at INTEGER NOT NULL,
  UNIQUE (task_id, day)
) STRICT;

CREATE TRIGGER tasks_drop_links AFTER DELETE ON tasks
BEGIN DELETE FROM tend_links WHERE source_type = 'TASK' AND source_id = OLD.id; END;

CREATE TABLE task_comments (
  id         TEXT PRIMARY KEY,
  task_id    TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  body       TEXT NOT NULL,              -- markdown
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL            -- later than created_at = edited
) STRICT;
CREATE INDEX task_comments_task ON task_comments(task_id, created_at);

CREATE TRIGGER task_comments_drop_links AFTER DELETE ON task_comments
BEGIN DELETE FROM tend_links WHERE source_type = 'COMMENT' AND source_id = OLD.id; END;

-------------------------------------------------------------------------------
-- 6. Library: words, snaps (in stacks), references (docs/decisions.md §15)
-------------------------------------------------------------------------------
-- Word kinds are WORD_KIND rows in tend_enums; `meta.lookup` says whether the dictionary is asked.
INSERT INTO tend_enums (id, kind, value, label, is_default, meta, created_at, updated_at) VALUES
  ('WORD_KIND:WORD',    'WORD_KIND', 'WORD',    'word',    1, '{"lookup":true,"position":0}',  0, 0),
  ('WORD_KIND:IDIOM',   'WORD_KIND', 'IDIOM',   'idiom',   1, '{"lookup":true,"position":1}',  0, 0),
  ('WORD_KIND:ABBR',    'WORD_KIND', 'ABBR',    'abbr',    1, '{"lookup":false,"position":2}', 0, 0),
  ('WORD_KIND:CONCEPT', 'WORD_KIND', 'CONCEPT', 'concept', 1, '{"lookup":false,"position":3}', 0, 0),
  ('WORD_KIND:PHRASE',  'WORD_KIND', 'PHRASE',  'phrase',  1, '{"lookup":true,"position":4}',  0, 0),
  ('WORD_KIND:TERM',    'WORD_KIND', 'TERM',    'term',    1, '{"lookup":false,"position":5}', 0, 0),
  ('WORD_KIND:OTHER',   'WORD_KIND', 'OTHER',   'other',   1, '{"lookup":false,"position":6}', 0, 0);

-- A title is unique by exact match; a WORD title is saved in lowercase (checked in the app).
CREATE TABLE words (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL UNIQUE,
  kind       TEXT NOT NULL DEFAULT 'WORD',   -- a WORD_KIND value
  dictionary TEXT,                           -- JSON from the lookup; NULL when not looked up or not found
  meaning    TEXT NOT NULL DEFAULT '',       -- markdown
  notes      TEXT NOT NULL DEFAULT '',       -- markdown
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

CREATE TRIGGER words_drop_links AFTER DELETE ON words
BEGIN DELETE FROM tend_links WHERE source_type = 'WORD' AND source_id = OLD.id; END;

-- Stacks group snaps like folders and nest; no stack is inside itself (checked in the app and by
-- sync). The name is free text; the UI shows "Untitled stack" when it is empty.
CREATE TABLE snap_stacks (
  id         TEXT PRIMARY KEY,
  parent_id  TEXT REFERENCES snap_stacks(id) ON DELETE SET NULL,   -- NULL = on the board
  name       TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX snap_stacks_parent ON snap_stacks(parent_id);

-- The board orders snaps by pinned, then updated_at; positions are never stored.
CREATE TABLE snaps (
  id         TEXT PRIMARY KEY,
  stack_id   TEXT REFERENCES snap_stacks(id) ON DELETE SET NULL,   -- NULL = loose on the board
  text       TEXT NOT NULL,
  paper      TEXT NOT NULL DEFAULT 'SCRAP',  -- SCRAP, SLIP, LINED, PLAIN, STICKY
  color      TEXT CHECK (color IS NULL OR color GLOB '#[0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]'),  -- sticky only
  pinned     INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX snaps_stack ON snaps(stack_id);

CREATE TRIGGER snaps_drop_links AFTER DELETE ON snaps
BEGIN DELETE FROM tend_links WHERE source_type = 'SNAP' AND source_id = OLD.id; END;

-- A reference is a link or text. `url_key` is a link's normalised URL (scheme, trailing slash and
-- case ignored) for the duplicate check; NULL for text.
CREATE TABLE refs (
  id         TEXT PRIMARY KEY,
  kind       TEXT NOT NULL,                  -- LINK, TEXT
  value      TEXT NOT NULL,                  -- the URL or the text as entered
  title      TEXT,                           -- fetched or typed; NULL falls back to the value
  why        TEXT NOT NULL DEFAULT '',
  url_key    TEXT UNIQUE,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;

CREATE TRIGGER refs_drop_links AFTER DELETE ON refs
BEGIN DELETE FROM tend_links WHERE source_type = 'REF' AND source_id = OLD.id; END;

-------------------------------------------------------------------------------
-- 7. Timers (local to the device)
-------------------------------------------------------------------------------
-- No background process. The window does the work:
--   create  → insert (title, ends_at, state 'running')
--   display → countdown = ends_at - now, recomputed every second
--   fire    → when now >= ends_at: desktop notification (+ sound), state = 'rung'
--   +1m / snooze → update ends_at;  cancel → state = 'cancelled'
--   on launch, running timers already past ends_at are shown once as "finished while closed"
CREATE TABLE timers (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL DEFAULT '',
  ends_at    INTEGER NOT NULL,
  state      TEXT NOT NULL DEFAULT 'running' CHECK (state IN ('running', 'rung', 'cancelled')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) STRICT;
CREATE INDEX timers_running ON timers(state, ends_at);

-------------------------------------------------------------------------------
-- 8. Feedback (local)
-------------------------------------------------------------------------------
CREATE TABLE feedback (
  id          TEXT PRIMARY KEY,
  kind        TEXT NOT NULL CHECK (kind IN ('bug', 'idea', 'other')),
  body        TEXT NOT NULL,
  app_version TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
) STRICT;

-------------------------------------------------------------------------------
-- 9. Sync bookkeeping (local)
-------------------------------------------------------------------------------
-- The base of the next sync merge (the commit both sides last agreed on) and how the last run went.
-- One row; local, never synced.
CREATE TABLE sync_state (
  id                 INTEGER PRIMARY KEY CHECK (id = 1),
  last_synced_commit TEXT,
  pending_commit     TEXT,               -- made and being pushed; the base once the remote has it
  last_run_at        INTEGER,
  last_result        TEXT,               -- 'ok', or an error key from the registry
  last_ok_at         INTEGER             -- the last run that ended 'ok'
) STRICT;
INSERT INTO sync_state (id) VALUES (1);

-- Every rename or move of a folder or note file, by Tend, a scan fixing a name or a sync, so an
-- earlier layout can be restored. Local; never synced; never trimmed.
CREATE TABLE path_log (
  id       INTEGER PRIMARY KEY,
  kind     TEXT NOT NULL CHECK (kind IN ('folder', 'note')),
  reason   TEXT NOT NULL CHECK (reason IN ('fix', 'rename', 'move', 'sync')),
  old_path TEXT NOT NULL,                -- relative to the vault, as it was
  new_path TEXT NOT NULL,
  at       INTEGER NOT NULL
) STRICT;
